fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single‐element slice trivially has all characters the same.
    // For longer slices, compare each byte to the first one.
    if let Some(&first) = s.first() {
        s.iter().all(|&c| c == first)
    } else {
        true
    }
}

